  "slots": [
    {
      "slot": 1,
      "stemPolarity": "SELECT_INCORRECT",
      "scope": "PASSAGE_WIDE",
      "concept": null,
      "answer": 4,
      "choices": [
        {
          "number": 1,
          "truth": "TRUE",
          "basis": [
            "따라서 법인의 자산이 개인의 출자에 의해 형성되었더라도 자산의 소유권은 특정 개인이 아닌 법인에게 귀속된다."
          ],
          "twist": null
        },
        {
          "number": 2,
          "truth": "TRUE",
          "basis": [
            "이렇게 법인의 자산이 법적 통제 아래 운용되는 것은 자율성과 책임의 균형을 통해 사회ㆍ경제 공동체의 질서를 유지하기 위함이다."
          ],
          "twist": null
        },
        {
          "number": 3,
          "truth": "TRUE",
          "basis": [
            "특히 법인의 목적 사업 수행을 위한 자산인 기본 재산은 재단을 설립할 때 정관에 기재해 등기해야 하고, 이를 처분하거나 용도를 변경하여 액수를 줄이려면 반드시 관할 기관의 허가가 필요하다."
          ],
          "twist": null
        },
        {
          "number": 4,
          "truth": "FALSE",
          "basis": [
            "주식회사는 사단 법인이면서 영리 법인으로, 법인격은 주식회사의 구성원 단체에 부여된다."
          ],
          "twist": {
            "label": "법인격 부여 대상 교체",
            "targetQuote": "법인격은 주식회사의 구성원 단체에 부여된다.",
            "change": "주식회사의 법인격 부여 대상을 구성원 단체에서 자산 자체로 바꾼다."
          }
        },
        {
          "number": 5,
          "truth": "TRUE",
          "basis": [
            "법인의 종류 및 자산 운용의 원칙은 민법에 규정되어 있지만, 주식회사와 같이 경제적 이익을 목적으로 하는 법인의 경우 구체적인 요건과 절차를 규정한 상법의 적용을 함께 받기 때문에 자산 운용에 관한 법적 통제가 보다 정교하게 제도화되어 있다고 할 수 있다."
          ],
          "twist": null
        }
      ]
    },
    {
      "slot": 2,
      "stemPolarity": "SELECT_CORRECT",
      "scope": "CONCEPT",
      "concept": "주식회사의 자산",
      "answer": 2,
      "choices": [
        {
          "number": 1,
          "truth": "FALSE",
          "basis": [
            "자본금은 주식을 발행하여 조달된 자금으로, 발행된 총 주식 수에 주식의 액면가*를 곱한 금액이다."
          ],
          "twist": {
            "label": "산정 기준 교체",
            "targetQuote": "발행된 총 주식 수에 주식의 액면가*를 곱한 금액이다.",
            "change": "자본금 산정에서 액면가에 곱하는 수량을 발행된 총 주식 수에서 주주의 수로 바꾼다."
          }
        },
        {
          "number": 2,
          "truth": "TRUE",
          "basis": [
            "자본금은 주식을 발행하여 조달된 자금으로, 발행된 총 주식 수에 주식의 액면가*를 곱한 금액이다.",
            "이는 회사의 지급 능력과 재무 안정성을 보장하는 기초 자산이므로 원칙적으로 감액이 금지된다."
          ],
          "twist": null
        },
        {
          "number": 3,
          "truth": "FALSE",
          "basis": [
            "이익 잉여금은 영업 활동에서 발생한 이익 중 사용되지 않고 유보된 재원으로,",
            "자본 잉여금은 주식 등 자본을 거래하여 얻은 이익으로"
          ],
          "twist": {
            "label": "재원 발생 경로 혼동",
            "targetQuote": "이익 잉여금은 영업 활동에서 발생한 이익 중 사용되지 않고 유보된 재원으로,",
            "change": "이익 잉여금의 발생 경로를 영업 활동에서 주식 등 자본의 거래로 바꾼다."
          }
        },
        {
          "number": 4,
          "truth": "FALSE",
          "basis": [
            "자본 잉여금은 주식 등 자본을 거래하여 얻은 이익으로 손실 보전 등의 제한된 목적으로만 사용될 수 있고, 배당금으로 지급될 수 없다."
          ],
          "twist": {
            "label": "금지된 용도 허용",
            "targetQuote": "배당금으로 지급될 수 없다.",
            "change": "자본 잉여금을 주주에게 배당금으로 지급할 수 없는 재원에서 지급할 수 있는 재원으로 바꾼다."
          }
        },
        {
          "number": 5,
          "truth": "FALSE",
          "basis": [
            "적자가 누적되어 이익 잉여금이나 자본 잉여금으로도 손실을 보전할 수 없는 경우에는 자본금을 사용하게 된다."
          ],
          "twist": {
            "label": "손실 보전 순서 역전",
            "targetQuote": "적자가 누적되어 이익 잉여금이나 자본 잉여금으로도 손실을 보전할 수 없는 경우에는 자본금을 사용하게 된다.",
            "change": "누적 적자를 보전할 때 잉여금으로 보전할 수 없는 경우 자본금을 사용하는 순서를 자본금을 먼저 사용하고 부족하면 잉여금을 사용하는 순서로 바꾼다."
          }
        }
      ]
    },
    {
      "slot": 3,
      "stemPolarity": "SELECT_INCORRECT",
      "scope": "CONCEPT",
      "concept": "무상 증자",
      "answer": 3,
      "choices": [
        {
          "number": 1,
          "truth": "TRUE",
          "basis": [
            "주식을 추가로 발행하여 주주들에게 무상으로 분배한다."
          ],
          "twist": null
        },
        {
          "number": 2,
          "truth": "TRUE",
          "basis": [
            "주식회사는 무상 증자를 실시하여 자본 잉여금이나 이익 잉여금의 일부 혹은 전부에 해당하는 만큼의 주식을 추가로 발행하여 주주들에게 무상으로 분배한다."
          ],
          "twist": null
        },
        {
          "number": 3,
          "truth": "FALSE",
          "basis": [
            "무상 증자를 실행하면 자산의 구조만 재편되고 자산의 총 규모는 변하지 않기 때문에"
          ],
          "twist": {
            "label": "자산 총규모 변화 왜곡",
            "targetQuote": "자산의 구조만 재편되고 자산의 총 규모는 변하지 않기 때문에",
            "change": "무상 증자에 따른 변화를 자산 구조의 재편과 총규모의 불변에서 추가 발행한 주식에 해당하는 만큼 자산 총규모가 증가하는 것으로 바꾼다."
          }
        },
        {
          "number": 4,
          "truth": "TRUE",
          "basis": [
            "이는 재무 구조가 안정적이라는 인상을 주어 주가의 상승을 유발할 수 있다."
          ],
          "twist": null
        },
        {
          "number": 5,
          "truth": "TRUE",
          "basis": [
            "이사회의 결정만으로 실행이 가능하다."
          ],
          "twist": null
        }
      ]
    }
  ]
}

